create table ai_party_status(company_id varchar(50), party_name varchar(255), party_type varchar(50), contact_number varchar(20), email varchar(150), address varchar(500), outstanding_balance decimal(14,2), balance_type varchar(10), last_bill_date date, last_bill_amount decimal(14,2), total_business_ytd decimal(14,2), credit_limit decimal(14,2), overdue_days int, gstin varchar(20));
create table ai_sales(company_id varchar(50), bill_no varchar(100), bill_date date, voucher_date time, party_name varchar(255), gross_amount decimal(14,2), discount_amount decimal(14,2), sgst_amount decimal(14,2), cgst_amount decimal(14,2), igst_amount decimal(14,2), invoice_amount decimal(14,2), taxable_amount decimal(14,2), payment_mode varchar(50), created_by varchar(100));
create table ai_daily_summary(company_id varchar(50), summary_date date, total_sales decimal(14,2), total_bills_count int, total_collection decimal(14,2), total_payment decimal(14,2), total_receivable decimal(14,2), total_payable decimal(14,2), cash_sales decimal(14,2), credit_sales decimal(14,2), total_discount_given decimal(14,2), total_purchase decimal(14,2));
